    // C's randrole() retries while it selects Priest itself (role index 6).
    if (game.urole?.key === 'priest') {
        do game._priestPantheonIndex = rn2(13);
        while (game._priestPantheonIndex === 6);
    }
    // random
    rn2(3); rn2(2);
